<?php
 require_once(__DIR__ . '/../../init.php'); class med_vaccinations_linkCertificateCovid19 { const TASK_NAME = 'medVaccinationsLinkCertificateCovid19'; const VACCINE_PROGRAM = 18; const VACCINE_DATATYPE = 1; const VACCINE_STR = 'Vaccine'; const CERTIFICATE_STR = 'Certificate'; const QRCODE_STR = 'QrCode'; const COUNTRY_CODE = 'BY'; const DEBUG_HTTP = true; private $db; private $extraSettings; public function getVaccines(){ $settings = $this->getSettings(); $request = $this->setupConnect(); if (!isset($request)) { $request = new stdClass(); $request->headers['Content-Type'] = "application/json"; $request->debug = true; $request->url = "http://apimis.nocovidtest.eh.mzrb/api/"; } $request->url = $request->url . self::VACCINE_STR; $catalog = httpGET($request); if (empty($catalog)){ $this->log("Нет ответа от " . $request->url, 2); return false; } $db = $this->db ?: $this->db = connectDb('mis'); $results = safe_json_decode($catalog['body']); if (isset($results)){ $db->beginTransaction(); try { $this->deleteUniImportLink(); $this->insertUniImportLink($results); $db->commit(); } catch (Throwable $e) { $db->rollback(); throw $e; } } else { $this->log(implode("\n", $catalog['body']), 2); $this->log('Ошибка json. ' . json_last_error() . ': ' . json_last_error_msg(), 2); return false; } $records = $this->readUniVaccine(); if (isset($records)){ $db->beginTransaction(); try { $this->updateMedVaccine($records); $db->commit(); } catch (Throwable $e) { $db->rollback(); throw $e; } } return true; } public function postCertificate($id){ if (!is_int($id)) { $this->log("Несохраненный сертификат " . $id, 2); throw new Exception('Перед регистрацией необходимо выполнить сохранение сертификата'); } $certificateData = $this->getCertificate($id); $notEmptyCertificateData = !empty($certificateData); $certificate = json_encode($certificateData, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES); switch (true) { case !$notEmptyCertificateData: $this->log("Нет сертификата с id = " . $id, 2); throw new Exception('Нет сертификата с id = ' . $id); case $notEmptyCertificateData && !empty($certificate->certificateId): $this->log("Cертификат " . $id . "уже зарегистрирован", 0); return $id; case $notEmptyCertificateData: $certificateResponse = $this->sendCertificateData($certificate); $_record = safe_json_decode($certificateResponse['body'])[0]; switch (true) { case empty($_record): $this->log("Нет ответа или он пустой " . $id, 2); throw new Exception('Нет ответа или он пустой'); case $_record->statusCode == 200: try { $updatedRec = $this->updateCertificate($id, $_record); $this->log("updateCertificate обновлена запись с id = " . $updatedRec, 0); return $id; } catch (Throwable $e) { $this->log("updateCertificate catch: " . $e->getCode() . '  ' . $e->getMessage(), 2); $this->log("updateCertificate catch: " . $e->getTraceAsString(), 2); throw $e; } break; default: $this->log('Код ответа: '. $_record->statusCode . '. '. $_record->statusMessage, 0); return $_record->statusMessage; } break; } return true; } private function deleteUniImportLink($program = self::VACCINE_PROGRAM, $dataType = self::VACCINE_DATATYPE){ $db = $this->db ?: $this->db = connectDb(); $stmtDelete = $db->prepare("DELETE FROM UniImportLink WHERE program = :program AND dataType = :dataType"); $stmtDelete->execute([':program' => $program, ':dataType' => $dataType]); return true; } private function insertUniImportLink($results){ $db = $this->db ?: $this->db = connectDb(); $sqlUniImportLink = <<<EOT
            INSERT INTO UniImportLink (code, dataType, name, note, program, updateTime)
            VALUES (:code, :dataType, :name, :note, :program, :updateTime)
EOT;
$stmtUniImportLink = $db->prepare($sqlUniImportLink); foreach ($results as $result) { $stmtUniImportLink->execute([ ':code' => isUndefinedProperty($result, 'code'), ':dataType' => self::VACCINE_DATATYPE, ':name' => isUndefinedProperty($result, 'name'), ':note' => json_encode($result, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES), ':program' => self::VACCINE_PROGRAM, ':updateTime' => dbDateTime(new DateTime()) ]); } return true; } public function readUniVaccine(){ $db = $this->db ?: $this->db = connectDb(); return selectSql($db, 'SELECT name, note FROM UniImportLink WHERE program = :program AND dataType = :dataType ORDER BY name', [':program' => self::VACCINE_PROGRAM, ':dataType' => self::VACCINE_DATATYPE] ); } private function updateMedVaccine($records){ $db = $this->db ?: $this->db = connectDb(); $rec = new stdClass; $sqlMedVaccine = <<<"EOT"
INSERT INTO MedVaccine (cipher, name, reportName) 
VALUES (:cipher, :name, :reportName) 
RETURNING medvaccinecode;
EOT;
$sqlMedInfection = <<<EOT
INSERT INTO MedInfection AS e (infectionType, name)
VALUES (:infectionType, :name)
RETURNING medInfectionCode
EOT;
$sqlMedVaccineInfection = <<<EOT
INSERT INTO MedVaccineInfection AS e (medInfectionCode, medVaccineCode)
VALUES (:medInfectionCode, :medVaccineCode)
ON CONFLICT (medInfectionCode, medVaccineCode)
DO NOTHING
EOT;
$stmtMedVaccine = $db->prepare($sqlMedVaccine); foreach($records as $record){ $_record = safe_json_decode($record['note']); try { $rec->idMedVaccine = selectSqlValue($db, "SELECT medVaccineCode FROM MedVaccine WHERE cipher = :cipher ORDER BY medVaccineCode LIMIT 1", [':cipher' => isEmptyProperty($_record, 'code')] ); if (isset($rec->idMedVaccine)) { selectSqlValue($db, "UPDATE MedVaccine SET (name, reportName) = (:name, :reportName) WHERE medVaccineCode = $rec->idMedVaccine;", [':name' => isEmptyProperty($_record, 'nameShort'), ':reportName' => isUndefinedProperty($_record, 'name')]); $this->log("MedVaccine обновило по cipher " . $_record->code, 0); } else { $rec->idMedVaccine = selectSqlValue($db, "SELECT medVaccineCode FROM MedVaccine WHERE name = :name ORDER BY medVaccineCode LIMIT 1", [':name' => isEmptyProperty($_record, 'nameShort')]); if (isset($rec->idMedVaccine)) { selectSqlValue($db, "UPDATE MedVaccine SET (cipher, reportName) = (:cipher, :reportName) WHERE medVaccineCode = $rec->idMedVaccine;", [':cipher' => isUndefinedProperty($_record, 'code'), ':reportName' => isUndefinedProperty($_record, 'name')]); $this->log("MedVaccine обновило по name " . $_record->nameShort, 0); } else { $stmtMedVaccine->execute([ ':cipher' => isUndefinedProperty($_record, 'code'), ':name' => isEmptyProperty($_record, 'nameShort'), ':reportName' => isUndefinedProperty($_record, 'name') ]); $this->log("MedVaccine записало новое" . $_record->code, 0); $rec->idMedVaccine = fetchValue($stmtMedVaccine, 'medvaccinecode'); } } } catch (Throwable $e) { $this->log("MedVaccine не записало " . $_record->code, 2); $this->log("MedVaccine " . $_record->name, 2); $this->log("MedVaccine ошибка: " . $e->getCode() . '  ' . $e->getMessage(), 2); $this->log("MedVaccine ошибка: " . $e->getTraceAsString(), 2); throw $e; } try { executeSql($db, 'UPDATE UniImportLink SET primarykey = '. $rec->idMedVaccine . 'WHERE code = :code', [':code' => isEmptyProperty($_record, 'code')]); $this->log("UniImportLink обновило " . $_record->code, 0); } catch (Throwable $e) { $this->log("UniImportLink не обновило " . $_record->code, 2); throw $e; } $stmtMedInfection = $db->prepare($sqlMedInfection); $rec->idMedInfection = selectSqlValue($db, 'SELECT medInfectionCode FROM MedInfection WHERE name = :name', [':name' => isEmptyProperty($_record, 'infectionName')] ); if (!isset($rec->idMedInfection)) { try { $stmtMedInfection->execute([':infectionType' => 1, ':name' => isEmptyProperty($_record, 'infectionName')]); $rec->idMedInfection = fetchValue($stmtMedVaccine, 'medinfectioncode'); $this->log("MedInfection записало " . $_record->infectionName, 0); } catch (Throwable $e) { $this->log("MedInfection не записало " . $_record->infectionName, 2); throw $e; } } $stmtMedVaccineInfection = $db->prepare($sqlMedVaccineInfection); try { $stmtMedVaccineInfection->execute([ ':medInfectionCode' => isEmptyProperty($rec, 'idMedInfection'), ':medVaccineCode' => isEmptyProperty($rec, 'idMedVaccine') ]); $this->log("MedVaccineInfection записало  " . $rec->idMedInfection . ' и ' . $rec->idMedVaccine, 0); } catch (Throwable $e) { $this->log("MedVaccineInfection не записало  " . $rec->idMedInfection . ' и ' . $rec->idMedVaccine, 2); throw $e; } $rec->idMedVaccine = null; $rec->idMedInfection = null; } return true; } private function getCertificate($id){ $certificateData = $this->getCertificateData($id); if ($certificateData) { $vaccinationsData = $this->getVaccinationsData($id); $certificateData[0]['vaccinations'] = $vaccinationsData; } return $certificateData; } private function getCertificateData($id){ $db = $this->db ?: $this->db = connectDb(); $settings = $this->getSettings(); $sql = <<<"EOT"
            SELECT
                COALESCE(mcc19.statusCode, 0) as statusCode, COALESCE(mcc19.statusMessage, '') as statusMessage, COALESCE(mcc19.certificateId, 0) as certificateId,
                mcc19.documentNumber as number, mcc19.issueDate as dateIssue, mcc19.nameLat as firstNameLat, mcc19.surnameLat as lastNameLat,
                cast(:organizationExternalGuid as varchar) as medicalOrganizationCode, e.fullName as medicalOrganizationName,
                mps.personalNumber as personalNumber, '' as passportSeries, mps.passportNumber as passportNumber, mps.dateOfBirth as birthDate,
                CASE mps.sex WHEN 1 THEN 0 WHEN 0 THEN 1 ELSE 2 END as gender,
                m.name as firstName, m.surname as lastName, m.secondName as patronymicName, 'BY' as countryCode
            FROM
                MedCertificateCovid19 mcc19
            JOIN Enterprise e ON e.enterpriseCode = mcc19.enterpriseCode
            JOIN EnterpriseNumber en ON en.enterpriseCode = e.enterpriseCode
            JOIN MedPatient mp ON mp.medPatientCode = mcc19.medPatientCode
            JOIN Man m ON m.manCode = mp.manCode
            JOIN ManPassport mps ON mps.manCode = m.manCode
            WHERE mcc19.medCertificateCovid19Code = :id
EOT;
$certificateData = selectSql($db, $sql, [':organizationExternalGuid' => $settings->organizationExternalGuid, ':id' => $id]); return $certificateData; } private function getVaccinationsData($id){ $db = $this->db ?: $this->db = connectDb(); $sql = <<<"EOT"
            SELECT
                mil.inoculateDate as dateVaccination, mil.reactionResult as patientCondition,
                FN_cmFIO(md.manCode) as doctor,
                mvp.doseSize, mvp.serial, mv.cipher as vaccineCode
            FROM
                MedInoculateLog mil
            JOIN MedVaccineMove mvm ON mvm.medInoculateLogCode = mil.medInoculateLogCode
            JOIN MedVaccineParty mvp ON mvp.medVaccinePartyCode = mvm.medVaccinePartyCode
            JOIN MedVaccine mv ON mv.medVaccineCode = mvp.medVaccineCode
            JOIN MedDoctor md ON md.medDoctorCode = mil.medDoctorCode
            WHERE mil.medCertificateCovid19Code = :id
EOT;
$vaccinationsData = selectSql($db, $sql, [':id' => $id]); return $vaccinationsData; } private function sendCertificateData($certificate){ $request = $this->setupConnect(); $request->url = $request->url . self::CERTIFICATE_STR; $request->request_content = $certificate; $response = httpPOST($request); if (empty($response)) { $ecode = httpError(); $estr = httpErrorStr(); $this->log("Ошибка HTTP запроса к " . $request->url . " при передаче сертификата. [$ecode - $estr]", 2); throw new Exception("Ошибка HTTP запроса к " . $request->url . " при передаче сертификата. [$ecode - $estr]"); } return $response; } private function updateCertificate($medCertificateCovid19Code, $_record) { $db = $this->db ?: $this->db = connectDb(); $qrCode = $this->getQrCode($_record->medicalOrganizationCode, $_record->certificateId); $qrCodeUrl = ''; !isset($qrCode['body']) ? $this->log("Пустой QR-код " , 0) : $this->log("QR-код: " . $qrCode['body'], 0); $maxDate = null; foreach ($_record->vaccinations as $i => $vaccination) { if ($vaccination->dateVaccination >= $maxDate) { $maxDate = $vaccination->dateVaccination; $qrCodeUrl = $vaccination->qrCodeStr; } } $this->log("QrCodeUrl: " . $qrCodeUrl, 0); try { $db->beginTransaction(); $updatedRec = selectSqlValue($db, "UPDATE MedCertificateCovid19 SET
                (certificateId, statusCode, statusMessage, qrCode, qrCodeUrl, registrationDate) =
                (:certificateId, :statusCode, :statusMessage, :qrCode::bytea, :qrCodeUrl, :registrationDate)
            WHERE medCertificateCovid19Code = :medCertificateCovid19Code
            RETURNING medCertificateCovid19Code", [':certificateId' => isEmptyProperty($_record, 'certificateId'), ':statusCode' => isEmptyProperty($_record, 'statusCode'), ':statusMessage' => isEmptyProperty($_record, 'statusMessage'), ':qrCode' => '\x' . bin2hex($qrCode['body']), ':qrCodeUrl' => $qrCodeUrl, ':registrationDate' => dbDateTime(new DateTime()), ':medCertificateCovid19Code' => $medCertificateCovid19Code] ); $this->log("MedCertificateCovid19 обновленная запись id = " . $updatedRec, 0); $db->commit(); } catch (Throwable $e) { $db->rollBack(); $this->log("MedCertificateCovid19 ошибка: " . $e->getCode() . '  ' . $e->getMessage(), 2); $this->log("MedCertificateCovid19 ошибка: " . $e->getTraceAsString(), 2); throw $e; } return $updatedRec; } private function getQrCode($medicalOrganizationCode, $certificateId){ $request = $this->setupConnect(); $request->url = $request->url . self::QRCODE_STR; $request->url = glueStrings($request->url, $medicalOrganizationCode, '/'); $request->url = glueStrings($request->url, $certificateId, '/'); $response = httpGET($request); if (empty($response)) { $ecode = httpError(); $estr = httpErrorStr(); $this->log("Ошибка HTTP запроса к " . $request->url . " при передаче сертификата. [$ecode - $estr]", 2); throw new Exception("Ошибка HTTP запроса к " . $request->url . " при передаче сертификата. [$ecode - $estr]"); } return $response; } private function setupConnect(): stdClass { $settings = $this->getSettings(); if (!httpCreateParam($settings)) { $message = "Ошибка инициализация подключюения"; $this->log($message, 1); throw new Exception($message); } $params = new stdClass(); $params->url = $settings->url; $params->proxy = $this->getProxySettings($settings); $params->headers['Content-Type'] = "application/json"; $params->debug = self::DEBUG_HTTP; return $params; } private function getSettings(){ if (!empty($this->extraSettings)) { return $this->extraSettings; } $this->log('Загрузка настроек...'); $settings = readExtraSettings($this->db, self::TASK_NAME); return $this->checkSettings($settings); } private function checkSettings($settings){ $settingsValid = true; if (empty($settings)) { $this->log('Не произведена настройка обмена информацией с ЦРБ', 2); } elseif (isset($settings->active) && $settings->active) { if (empty($settings->url)) { $this->log('Не заполнена настройка Адрес сервера', 2); $settingsValid = false; } if ($settingsValid) { $settings->task = self::TASK_NAME; $this->log('Настройки загружены успешно'); $this->extraSettings = $settings; $result = $this->extraSettings; } else { throw new Exception('Проверьте правильность заполнения данных для подключения.'); } } else { $this->log('В настройках запрещен обмен данными', 1); throw new Exception('В настройках запрещен обмен данными'); } return $result; } private function getProxySettings($settings){ return $settings->proxyUse ? array( 'host' => isEmptyProperty($settings, 'proxyServer', ''), 'port' => isEmptyProperty($settings, 'proxyPort', 0), 'usr' => isEmptyProperty($settings, 'proxyUser', ''), 'pwd' => isEmptyProperty($settings, 'proxyPassword', '') ) : array(); } private function log($message, $type = 0){ app_log($message, $type, self::TASK_NAME); } } handleJsonRpc('med_vaccinations_linkCertificateCovid19');